tatus\"::string AS \"Sale Order Status\", _AIRBYTE_DATA:\"Seller SKU Code\"::string AS \"Seller SKU Code\", _AIRBYTE_DATA:\"Selling Price\"::string AS \"Selling Price\", _AIRBYTE_DATA:\"Shipping Address City\"::string AS \"Shipping Address City\", _AIRBYTE_DATA:\"Shipping Address Country\"::string AS \"Shipping Address Country\", _AIRBYTE_DATA:\"Shipping Address Id\"::string AS \"Shipping Address Id\", _AIRBYTE_DATA:\"Shipping Address Line 1\"::string AS \"Shipping Address Line 1\", _AIRBYTE_DATA:\"Shipping Address Line 2\"::string AS \"Shipping Address Line 2\", _AIRBYTE_DATA:\"Shipping Address Name\"::string AS \"Shipping Address Name\", _AIRBYTE_DATA:\"Shipping Address Phone\"::string AS \"Shipping Address Phone\", _AIRBYTE_DATA:\"Shipping Address Pincode\"::string AS \"Shipping Address Pincode\", _AIRBYTE_DATA:\"Shipping Address State\"::string AS \"Shipping Address State\", _AIRBYTE_DATA:\"Shipping Arranged By\"::string AS \"Shipping Arranged By\", _AIRBYTE_DATA:\"Shipping Charges\"::string AS \"Shipping Charges\", _AIRBYTE_DATA:\"Total Price\"::string AS \"Total Price\", _AIRBYTE_DATA:\"Tracking Number\"::string AS \"Tracking Number\", _AIRBYTE_DATA:\"Updated\"::string AS Updated, _AIRBYTE_DATA:\"Warehouse Name\"::string AS \"Warehouse Name\", _AIRBYTE_DATA: \"Shipping Package Status Code\"::string AS \"Shipping Package Status Code\", _AIRBYTE_DATA: \"Order Date as dd/mm/yyyy hh:MM:ss\" :: string AS \"Order Date as dd/mm/yyyy hh:MM:ss\", _AIRBYTE_DATA:\"Shipping Package Creation Date\"::string AS \"Shipping Package Creation Date\", _AIRBYTE_DATA: \"Tax Value\" ::string AS \"Tax Value\", _AIRBYTE_DATA: \"Shipping Package Code\"::string AS \"Shipping Package Code\", _AIRBYTE_DATA: \"Shipping provider\"::string AS \"Shipping provider\", _AIRBYTE_DATA: \"Shipping Tracking Status\" ::string AS \"Shipping Tracking Status\", _AIRBYTE_DATA: \"Shipping Courier\"::string AS \"Shipping Courier\", _AIRBYTE_DATA: \"Shipping Package Type\"::string AS \"Shipping Package Type\", _AIRBYTE_DATA: \"Width(mm)\"::string AS \"Width(mm)\", _AIRBYTE_DATA: \"weight\"::string AS weight, _AIRBYTE_DATA: \"Shipping Courier Status\"::string as \"Shipping Courier Status\", _AIRBYTE_DATA: \"Order_Type\"::string as \"Order_Type\", _AIRBYTE_DATA: \"STORE-CODE\"::string as \"STORE-CODE\", _AIRBYTE_DATA: \"SaleInvoicePrefix\"::string as \"SaleInvoicePrefix\", _AIRBYTE_DATA: \"Order Amount\"::string as \"Order Amount\" FROM snitch_db.maplemonk._airbyte_raw_Snitch_uc_New_get_sale_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Code\"::string, \"Display Order Code\"::string, \"Sale Order Item Code\"::string ORDER BY TRY_CAST(Updated::string AS TIMESTAMP) DESC ) = 1 ), ranked_data AS ( SELECT \"Channel Name\" AS MARKETPLACE, CASE WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%M-NOW%\' THEN \'M-NOW\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' and UPPER(TRIM(\"Channel Name\")) LIKE \'%CUSTOM%\' THEN \'FLIPKART_SOR\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%MYNTRA%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%STORE%\' THEN \'STORE\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA_FASHION%\' THEN \'NYKAA_FASHION\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA_COM%\' THEN \'NYKAA.COM\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA%\' THEN \'NYKAA.COM\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%INSTA%\' THEN \'INSTAMART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NOON%\' THEN \'NOON\' ELSE UPPER(\"Channel Name\") END AS MARKETPLACE_MAPPED, \"Display Order Code\" AS order_name, CASE WHEN LEFT(\"Sale Order Code\", 1) = \'`\' THEN SUBSTRING(\"Sale Order Code\", 2, LENGTH(\"Sale Order Code\") - 1) ELSE \"Sale Order Code\" END AS order_id, TO_VARCHAR(\"Shipping Address Name\") AS NAME, \"Fulfillment TAT\" AS FULFILLMENT_TAT, NULLIF(CREATED, \'\')::TIMESTAMP AS UC_CREATED, NULLIF(UPDATED, \'\')::DATE AS SHIPPING_LAST_UPDATE_DATE, NULLIF(UPDATED, \'\')::TIMESTAMP AS SHIPPING_LAST_UPDATE_TIMESTAMP, \"Item SKU Code\" AS SKU, LEFT(\"Item SKU Code\", LENGTH(\"Item SKU Code\") - CHARINDEX(\'-\', REVERSE(\"Item SKU Code\"))) AS SKU_GROUP, \"Channel Product Id\" AS PRODUCT_ID, CASE WHEN \"Sale Order Item Status\" LIKE \'PICKING_%\' THEN \"Shipping Package Status Code\" ELSE \"Sale Order Item Status\" END AS SALE_ORDER_ITEM_STATUS, \"Item Details\" AS ITEM_DETAILS, \"Shipping Address Line 1\" AS ADDRESS_LINE_1, \"Shipping Address Line 2\" AS ADDRESS_LINE_2, nullif(\"Shipping Address City\",\'\') AS CITY, nullif(\"Shipping Address State\",\'\') AS STATE, \"Shipping Address Country\" AS COUNTRY, \"Shipping Address Pincode\" AS PINCODE, \"Sale Order Status\" AS ORDER_STATUS, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::DATE AS ORDER_DATE, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::TIMESTAMP AS ORDER_TIMESTAMP, NULLIF(\"Shipping Package Creation Date\", \'\')::TIMESTAMP AS SHIPPING_PACKAGE_CREATED, \'1\' AS SUBORDER_QUANTITY, coalesce(nullif(discount,\'\'),0) AS DISCOUNT, \"Tax Value\" AS TAX, coalesce(nullif(TRIM(\"Selling Price\"),\'\'),0) AS SELLING_PRICE, NULLIF(\"Shipping Package Code\", \'\') AS SHIPPINGPACKAGECODE, \"Shipping Package Status Code\" AS SHIPPINGPACKAGESTATUS, facility AS WAREHOUSE_NAME, CASE WHEN LEFT(\"Sale Order Item Code\", 1) = \'`\' THEN SUBSTRING(\"Sale Order Item Code\", 2, LENGTH(\"Sale Order Item Code\") - 1) ELSE \"Sale Order Item Code\" END AS SALEORDERITEMCODE, coalesce(nullif(mrp,\'\'),0) AS MRP, nullif(discountcode,\'\') as DISCOUNT_CODE, \"Shipping provider\" AS COURIER, \"Shipping Tracking Status\" AS SHIPPING_STATUS, NULLIF(\"Shipping Package Creation Date\", \'\')::DATE AS CREATED_TIMESTAMP, NULLIF(\"Packing Time\", \'\')::DATE AS PACKED_TIMESTAMP, NULLIF(\"Dispatch Date\", \'\')::DATE AS DISPATCH_DATE, NULLIF(\"Dispatch Date\", \'\')::TIMESTAMP AS DISPATCHED_TIMESTAMP, NULLIF(\"Delivery Time\", \'\')::DATE AS DELIVERED_DATE, NULLIF(\"Delivery Time\", \'\')::TIMESTAMP AS DELIVERED_TIMESTAMP, category, coalesce(nullif(\"Cost Price\",\'\'),0) AS COST, \"Invoice Code\" as INVOICE_CODE, NULLIF(\"Invoice Created\", \'\')::TIMESTAMP AS INVOICE_DATE, \"Tracking Number\" AS AWB, \"Shipping Courier\" AS SHIPPING_COURIER, ROW_NUMBER() OVER (PARTITION BY CONCAT(\"Sale Order Item Code\",\"Display Order Code\",\"Sale Order Code\") ORDER BY NULLIF(UPDATED, \'\') DESC) AS row_num, \"On Hold\" as ON_HOLD, \"Shipping Package Type\" AS SHIPPING_PACKAGE_TYPE, \"Reverse Pickup Code\" as REVERSE_PICKUP_CODE, NULLIF(\"Reverse Pickup Created Date\", \'\')::TIMESTAMP AS REVERSE_PICKUP_CREATED, \"Notification Email\" as NOTIFICATION_EMAIL, \"Notification Mobile\" as NOTIFICATION_MOBILE, \"Require Customization\" as CUSTOMIZATION, COD, \"Shipping Address Id\" as SHIPPING_ID, \"Cancellation Reason\" as CANCELLATION_REASON, \"Shipping Arranged By\" as SHIPPING_ARRANGED_BY, \"Length(mm)\" as PACKAGE_LENGTH, \"Width(mm)\" as PACKAGE_WIDTH, \"Height(mm)\" as PACKAGE_HEIGHT, NULLIF(\"Return Date\", \'\')::TIMESTAMP AS RETURN_DATE, \"Return Reason\" as RETURN_REASON, \"Return Remarks\" as RETURN_REMARKS, \"Item Code\" as ITEM_CODE, weight, \"SKU Name\" as SKU_NAME, \"Shipping Courier Status\" as SHIPPING_COURIER_STATUS, \"Shipping Tracking Status\" as SHIPPING_TRACKING_STATUS, NULLIF(\"Packing Time\", \'\')::TIMESTAMP AS PACKED_TIME, \"Packing User\" as PACKING_USER, CASE WHEN SHIPPING_COURIER_STATUS in (\'COURIER_RETURN-CREATED\',\'COURIER_RETURN-RETURN_CREATED\',\'COURIER_RETURN-CONFIRMED\') then \'DTO-INPROCESS\' WHEN SHIPPING_COURIER_STATUS like \'%ORIGIN%\' then \'RTO\' WHEN SHIPPING_COURIER_STATUS like \'%COURIER_RETURN%\' then \'DTO\' WHEN SHIPPING_COURIER_STATUS in (\'DISPATCHED\',\'PICKED\',\'SHIPPED\',\'PENDING\') then \'INTRANSIT\' WHEN SHIPPING_COURIER_STATUS like \'%REFUSED_TO_ACCEPT%\' then \'RTO\' WHEN SHIPPING_COURIER_STATUS in (\'DELIVERED\') then \'DELIVERED\' when DISPATCH_DATE is null and SALE_ORDER_ITEM_STATUS like \'%CAN%\' then \'CANCELLED\' when SALE_ORDER_ITEM_STATUS in (\'CREATED\', \'MANIFESTED\', \'PICKING\', \'PICKED\', \'PACKED\', \'READY_TO_SHIP\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\',\'SHIPPED\',\'UNFULFILLABLE\',\'PENDING_CUSTOMIZATION\') THEN \'PROCESSING\' END AS ITEM_FINAL_STATUS, NULLIF(\"Order_Type\",\'\') as order_type, NULLIF(\"STORE-CODE\",\'\') as store_code, NULLIF(\"SaleInvoicePrefix\",\'\') as saleinvoiceprefix, NULLIF(\"Order Amount\",\'\') as ORDER_AMOUNT FROM Base_Data where \"Require Customization\" not in (\'STD\') and COD in (\'1\',\'0\') ) SELECT * FROM ranked_data WHERE row_num = 1 ; INSERT INTO snitch_db.maplemonk.switch_check_storing_shopify select order_name, warehouse_name, saleorderitemcode, concat(order_name,warehouse_name,saleorderitemcode) as identity from snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_date >= \'2026-01-25\' and marketplace_mapped = \'SHOPIFY\' and saleorderitemcode not in (select saleorderitemcode from snitch_db.maplemonk.switch_check_storing_shopify) ; INSERT INTO snitch_db.maplemonk.SF_EXCHANGE_WH_STORING SELECT CURRENT_TIMESTAMP AS ADDED_ON, warehouse_name, order_name, saleorderitemcode, order_id, order_status FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 w WHERE order_status LIKE \'%PENDIN%\' AND warehouse_name LIKE \'%SAPL%\' AND NOT EXISTS ( SELECT 1 FROM snitch_db.maplemonk.SF_EXCHANGE_WH_STORING AS log WHERE log.saleorderitemcode = w.saleorderitemcode ); create or replace table snitch_db.maplemonk.warehouse_sla_performance as WITH unicom AS ( SELECT awb, MARKETPLACE, marketplace_mapped, shippingpackagecode, order_id, order_name, SELLING_PRICE, saleorderitemcode, sku, order_status, order_date, order_timestamp, SHIPPING_LAST_UPDATE_TIMESTAMP, shipping_courier, warehouse_name, shipping_status, ON_HOLD, CASE WHEN SALE_ORDER_ITEM_STATUS = \'PICKING_FOR_INVOICING\' THEN shippingpackagestatus ELSE SALE_ORDER_ITEM_STATUS END AS UC_STATUS, dispatched_timestamp AS \"UC_Dispatched\", dispatch_date, delivered_date, item_details, address_line_1, uc_created, CASE WHEN upper(MARKETPLACE) = \'SHOPIFY\' THEN CASE WHEN uc_created::DATE in (\'2025-11-26\',\'2025-11-27\',\'2025-11-28\',\'2025-11-29\',\'2025-11-30\',\'2025-12-01\',\'2025-12-02\') THEN DATEADD(HOUR, 12, uc_created::timestamp) WHEN order_date > \'2024-09-20\' THEN CASE WHEN upper(warehouse_name) = \'SAPL-WH2\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 3 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'5 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 3 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'5 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL-WH1\' and order_date >= \'2025-05-20\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 3 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'5 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 3 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'5 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL_EMIZA\' and order_Date >= \'2025-04-01\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 4 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'6 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 4 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'6 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL-NORTH-TAURU\' and order_Date >= \'2025-11-20\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 4 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'6 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 4 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'6 hours\' ELSE fulfillment_tat END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE fulfillment_tat END AS TAT, category, SHIPPING_PACKAGE_TYPE, REVERSE_PICKUP_CODE, REVERSE_PICKUP_CREATED, NOTIFICATION_EMAIL, NOTIFICATION_MOBILE, CUSTOMIZATION, DISCOUNT_CODE, COD, SHIPPING_ID, CANCELLATION_REASON, SHIPPING_ARRANGED_BY, PACKAGE_LENGTH, PACKAGE_WIDTH, PACKAGE_HEIGHT, RETURN_DATE, RETURN_REASON, RETURN_REMARKS, ITEM_CODE, weight, SKU_NAME, SHIPPING_COURIER_STATUS, SHIPPING_TRACKING_STATUS, PACKED_TIME, PACKING_USER, ITEM_FINAL_STATUS, order_type, store_code, saleinvoiceprefix, ORDER_AMOUNT FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_Date >= current_date - 90 ), forward AS ( SELECT \"Shipping Package Code\", created_timestamp, picking_timestamp, picked_timestamp, packed_timestamp, rts_timestamp, manifested_timestamp, dispatched_timestamp AS dispatched_timestamp1, shipped_timestamp, delivered_timestamp, cancelled_timestamp, \"created&dispatch\", \"pick&dispatch\", \"pack&dispatch\", LATEST_STATUS, LAST_UPDATED FROM snitch_db.maplemonk.forward_timestamps ), clickpost AS ( SELECT awb, \"Order Date\" AS CP_orderplaced, \"Pickup Date\", \"Delivery Date\" AS CP_Delivery, \"Clickpost Unified Status\" as CP_STATUS FROM snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report ), sr AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_SR ), wh AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH ), wh2 AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH2 ), emiza AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_EMIZA ), marketplace AS ( (SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_MARKET_PLACE_ERROR_ORDERS ) UNION ALL (select \"Order ID\", warehouse from snitch_db.maplemonk.gs_mp_error_north) ), unicom_error AS ( SELECT u.*, CASE WHEN u.marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN u.warehouse_name = \'SAPL_EMIZA\' AND EXISTS (SELECT 1 FROM emiza WHERE emiza.\"Order ID\" = u.order_name AND emiza.warehouse = \'SAPL_EMIZA\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH1\' AND EXISTS (SELECT 1 FROM wh WHERE wh.\"Order ID\" = u.order_name AND wh.warehouse = \'SAPL-WH1\') THEN 1 WHEN u.warehouse_name = \'SAPL-NORTH-TAURU\' AND EXISTS (SELECT 1 FROM sr WHERE sr.\"Order ID\" = u.order_name AND sr.warehouse = \'SAPL-NORTH-TAURU\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH2\' AND EXISTS (SELECT 1 FROM wh2 WHERE wh2.\"Order ID\" = u.order_name AND wh2.warehouse = \'SAPL-WH2\') THEN 1 ELSE NULL END WHEN u.marketplace_mapped NOT IN (\'SHOPIFY\', \'OWN_STORE\', \'FRANCHISE_STORE\') THEN CASE WHEN EXISTS (SELECT 1 FROM marketplace WHERE marketplace.\"Order ID\" = u.order_name AND marketplace.warehouse = u.warehouse_name) THEN 1 ELSE NULL END ELSE NULL END AS ERROR FROM unicom u ), main_data AS ( SELECT ue.*, f.created_timestamp, f.picking_timestamp, f.picked_timestamp, f.packed_timestamp, f.rts_timestamp, f.manifested_timestamp, f.dispatched_timestamp1, f.shipped_timestamp, f.delivered_timestamp, f.cancelled_timestamp, f.\"created&dispatch\", f.\"pick&dispatch\", f.\"pack&dispatch\", f.LATEST_STATUS, f.LAST_UPDATED, cp.CP_orderplaced, cp.\"Pickup Date\", cp.CP_Delivery, cp.CP_STATUS FROM unicom_error ue LEFT JOIN forward f ON ue.shippingpackagecode = f.\"Shipping Package Code\" LEFT JOIN clickpost cp ON ue.awb = cp.awb ), over AS ( SELECT don, soic, facwarehouse, overrulestatus FROM snitch_db.maplemonk.gs_overrule ), mast1 AS ( SELECT md.*, ov.* FROM main_data md LEFT JOIN over ov ON md.saleorderitemcode = ov.soic ), new_status AS ( SELECT m1.*, CASE when overrulestatus = \'DISPATCHED\' THEN created_timestamp END AS dispatchedtimestamp1, COALESCE(COALESCE(dispatchedtimestamp1,dispatched_timestamp1),\"UC_Dispatched\") AS dispatched_timestamp, CASE WHEN last_updated > SHIPPING_LAST_UPDATE_TIMESTAMP THEN LATEST_STATUS ELSE UC_STATUS END AS ITEM_STATUS1, coalesce (overrulestatus,ITEM_STATUS1) as ITEM_STATUS, CASE WHEN ITEM_STATUS = \'CANCELLED\' THEN CASE WHEN dispatched_timestamp IS NULL THEN \'CANCELLED\' ELSE CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END END WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-COMPLETED\' WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS NOT IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-PENDING\' ELSE CASE WHEN ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\') THEN CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN ITEM_STATUS IN (\'CREATED\', \'MANIFESTED\', \'PICKING\', \'PICKED\', \'PACKED\', \'READY_TO_SHIP\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\') THEN \'BREACHED - PENDING FOR PROCESS\' WHEN ITEM_STATUS = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'BREACHED\' END END AS SLA_Status, CASE WHEN marketplace_mapped = \'MYNTRA\' THEN CASE WHEN LOWER(SLA_Status) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(SLA_Status) NOT IN (\'cancelled\', \'within sla\', \'breached\', \'future date-completed\') THEN \'PENDING\' ELSE CASE WHEN category IN (\'Accessories\', \'Sunglass\', \'Shorts\', \'Pyjama\', \'Boxer\', \'Co-ords\', \'Jogsuit\', \'Underpants\') AND item_details IS NULL THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%mp%\' THEN \'CORRECT\' ELSE \'INCORRECT\' END END ELSE \'OTHER CHANNEL\' END AS Myntra_Tag_Loops, CASE WHEN marketplace_mapped like \'%AJIO%\' THEN \'MP_Shift_TAT\' WHEN EXTRACT(HOUR FROM TAT) < 7 THEN \'Night_Shift_TAT\' WHEN EXTRACT(HOUR FROM TAT) = 18 THEN \'Day_Shift_TAT\' ELSE \'MP_SHIFT_TAT\' END AS tat_type , CASE WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 0 THEN \'D0\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'D1\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 2 THEN \'D2\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 3 THEN \'D3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 3 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 5 THEN \'D>3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 5 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 7 THEN \'D>5\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 7 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 9 THEN \'D>7\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 9 THEN \'D>9\' END AS Ageing, case when dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' AND cp_status not in (\'Cancelled\',\'RTO-Delivered\') THEN \'Handover_Pending\' ELSE \'NA\' END AS handover_status, CASE WHEN dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) < 12 THEN \'<12H\' WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 12 AND 24 THEN \'1D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'2D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 2 AND 5 THEN \'5D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 5 AND 10 THEN \'10D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 10 AND 30 THEN \'30D\' ELSE \'30D+\' END ELSE \'NA\' END as handover_ageing FROM mast1 m1 ), final123 as (select n.*, case when e.saleorderitemcode is not null then 1 else null end as exchange_flag from new_status n left join snitch_db.maplemonk.SF_EXCHANGE_WH_STORING e on n.saleorderitemcode = e.saleorderitemcode) SELECT * FROM final123 WHERE (warehouse_name LIKE \'%SAPL%\' OR warehouse_name IS NULL or warehouse_name like \'%Surat%\') ; INSERT INTO snitch_db.maplemonk.UF_COUNT_CHECK1 SELECT CURRENT_TIMESTAMP AS ADDED_ON ,AWB ,MARKETPLACE ,MARKETPLACE_MAPPED ,SHIPPINGPACKAGECODE ,ORDER_ID ,ORDER_NAME ,SELLING_PRICE ,SALEORDERITEMCODE ,SKU ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,SHIPPING_LAST_UPDATE_TIMESTAMP ,SHIPPING_COURIER ,WAREHOUSE_NAME ,SHIPPING_STATUS ,null as SKU_GROUP ,ON_HOLD ,UC_STATUS ,\"UC_Dispatched\" ,DISPATCH_DATE ,DELIVERED_DATE ,ITEM_DETAILS ,ADDRESS_LINE_1 ,UC_CREATED ,TAT ,CATEGORY ,SHIPPING_PACKAGE_TYPE ,REVERSE_PICKUP_CODE ,REVERSE_PICKUP_CREATED ,NOTIFICATION_EMAIL ,NOTIFICATION_MOBILE ,CUSTOMIZATION ,DISCOUNT_CODE ,COD ,SHIPPING_ID ,CANCELLATION_REASON ,SHIPPING_ARRANGED_BY ,PACKAGE_LENGTH ,PACKAGE_WIDTH ,PACKAGE_HEIGHT ,RETURN_DATE ,RETURN_REASON ,RETURN_REMARKS ,ITEM_CODE ,WEIGHT ,SKU_NAME ,SHIPPING_COURIER_STATUS ,SHIPPING_TRACKING_STATUS ,PACKED_TIME ,PACKING_USER ,ITEM_FINAL_STATUS ,ERROR ,CREATED_TIMESTAMP ,PICKING_TIMESTAMP ,PICKED_TIMESTAMP ,PACKED_TIMESTAMP ,RTS_TIMESTAMP ,MANIFESTED_TIMESTAMP ,DISPATCHED_TIMESTAMP1 ,SHIPPED_TIMESTAMP ,DELIVERED_TIMESTAMP ,CANCELLED_TIMESTAMP ,\"created&dispatch\" ,\"pick&dispatch\" ,\"pack&dispatch\" ,LATEST_STATUS ,LAST_UPDATED ,CP_ORDERPLACED ,\"Pickup Date\" ,CP_DELIVERY ,CP_STATUS ,DON ,SOIC ,FACWAREHOUSE ,OVERRULESTATUS ,DISPATCHEDTIMESTAMP1 ,DISPATCHED_TIMESTAMP ,ITEM_STATUS ,SLA_STATUS ,MYNTRA_TAG_LOOPS ,TAT_TYPE ,AGEING ,HANDOVER_STATUS ,HANDOVER_AGEING FROM snitch_db.maplemonk.warehouse_sla_performance AS w WHERE w.item_status = \'UNFULFILLABLE\' and w.warehouse_name like \'%SAPL%\' AND NOT EXISTS ( SELECT 1 FROM snitch_db.maplemonk.UF_COUNT_CHECK AS log WHERE log.saleorderitemcode = w.saleorderitemcode ) ; CREATE OR REPLACE TABLE snitch_db.maplemonk.uf_count_check as with data as ( select * from snitch_db.maplemonk.uf_count_Check1 where warehouse_name like \'%SAPL%\' ), new as (select saleorderitemcode as s1 , item_status as final_status from snitch_db.maplemonk.warehouse_sla_performance ) , final as ( select CASE WHEN n.final_status = \'CANCELLED\' THEN \'CANCELLED\' WHEN n.final_status = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' WHEN n.final_status in (\'DELIVERED\',\'DISPATCHED\') THEN \'PROCESSED\' ELSE \'PROCESSING\' END AS FINAL_STATUS, d.* from data d inner join new n on d.saleorderitemcode = n.s1 ) select * from final ; CREATE OR REPLACE TABLE snitch_db.maplemonk.switch_storing as with switch as ( select * from snitch_db.maplemonk.switch_check_storing_shopify ), uc as ( select saleorderitemcode as s2, warehouse_name as new_facility, concat(order_name, warehouse_name, saleorderitemcode ) as ident2 from snitch_db.maplemonk.warehouse_sla_performance where order_Date >= \'2026-01-25\' and marketplace_mapped = \'SHOPIFY\' ), final1 as ( select order_name, saleorderitemcode , warehouse_name, new_facility, CASE WHEN identity != ident2 then 1 else null end as switch_flag from switch s left join uc u on s.saleorderitemcode = u.s2 ) select * from final1 where switch_flag is not null ;",
                    "transaction": true
